/// <summary>
/// 675_TM Carrier instructions by bankaak
/// </summary>
public class METWarehouseCarrierCustomer extends common
{
}

Method.Source:
    /// <summary>
    /// Find method to fetch the table reference based on input parameter
    /// </summary>
    /// <param name = "_warehouseCarrieCustomerId">Warehouse carrier customer Id reference</param>
    /// <param name = "_custAccount">Customer account reference</param>
    /// <param name = "_forUpdate">Boolean value to update table</param>
    /// <returns>METWarehouseCarrierCustomer reference</returns>
    public static METWarehouseCarrierCustomer find(METWarehouseCarrierCustomerId    _warehouseCarrieCustomerId,
                                                CustAccount                         _custAccount = '',
                                                boolean                             _forUpdate = false)
    {
        METWarehouseCarrierCustomer metWarehouseCarrierCustomer;

        if (_forUpdate)
        {
            metWarehouseCarrierCustomer.selectForUpdate(_forUpdate);
        }

        if (_custAccount)
        {
            select firstonly metWarehouseCarrierCustomer
                where metWarehouseCarrierCustomer.WarehouseCarrierCustomerId == _warehouseCarrieCustomerId &&
                    metWarehouseCarrierCustomer.CustAccount == _custAccount;
        }
        else
        {
            select firstonly metWarehouseCarrierCustomer
                where metWarehouseCarrierCustomer.WarehouseCarrierCustomerId == _warehouseCarrieCustomerId;
        }

        return metWarehouseCarrierCustomer;
    }

/// <summary>
/// Method to check existance of record in table
/// </summary>
/// <param name = "_warehouseCarrieCustomerrId">Warehouse carrier Id reference</param>
/// <returns>Boolean value</returns>
public static boolean exist(METWarehouseCarrierCustomerId    _warehouseCarrieCustomerrId)
{
    return _warehouseCarrieCustomerrId && (select firstonly RecId from metWarehouseCarrierCustomer
                    where metWarehouseCarrierCustomer.WarehouseCarrierCustomerId == _warehouseCarrieCustomerrId).RecId != 0;
}
